  // ── Лента новостей: слова из заголовков ────────────────────────────────────
  //
  // ЗАЧЕМ ОНИ ЗДЕСЬ. Заголовок автоматической ленты (data/feed/autoKo.ts) —
  // единственный текст видео-поста, и он разбирается по словам, как абзац
  // заметки. Но корейский лексикон откусывает по одному слогу всё, чего нет в
  // словаре целым словом: 공항 «аэропорт» рассыпался на 공 + 항, и на каждый
  // тап ученик получал «этого слова нет в словаре». Слоги добавлять нельзя —
  // 공 само по себе не слово; лечится только целыми словами, что и сделано.
  //
  // Автолента перезаписывается сборкой каждый день, но словарь ПОСТОЯННЫЙ:
  // «аэропорт», «труд», «переработка» вернутся в завтрашних новостях, поэтому
  // покрытие копится, а не сгорает вместе с файлом ленты.
  //
  // ЭТИХ СЛОВ НЕ ВИДИТ `npm run check:gloss`: сторож импортирует feedKo, а
  // autoKo — нет, и намеренно (он падал бы каждое утро на свежих новостях).
