/** Словари по коду языка. Языка нет в карте — пословный перевод просто не работает. */
// ─── Немецкий ────────────────────────────────────────────────────────────────
//
// ФОРМЫ ЗАПИСАНЫ ТАК, КАК ОНИ СТОЯТ В ТЕКСТЕ. У немецкого богатое
// словоизменение (dem, den, des; wird, wurde, werden), а автоматически резать
// окончания здесь нельзя: den — это и артикль, и часть denen, а wird и wurde
// различаются временем, а не опечаткой. Поэтому артикли, формы вспомогательных
// глаголов и предлоги лежат отдельными записями, а знаменательные слова — в той
// форме, в какой встретились, с пометкой словарной формы там, где это важно.
//
// РЕГИСТР НЕ ЗНАЧИМ: разборщик приводит ключ к нижнему регистру (lib/lexicon),
// поэтому Die и die — одна запись. Для немецкого это удобно вдвойне:
// существительные всегда с прописной, а те же слова внутри сложных — со
// строчной.

